def apply(path, edits):
    t = path.read_text()
    for old, new in edits:
        assert t.count(old) == 1, (path.name, old[:80], t.count(old))
        t = t.replace(old, new)
    path.write_text(t)
    print(path.name, len(edits), 'edits')


